insert into public.sat_question_bank(id,practice_test_id,subject,module,question_number,source_page,answer_page,correct_answer,accepted_answers,response_type,question_lines,explanation_lines,needs_visual,content_status,question_mode)
values
('practice-test-8:rw1-1','practice-test-8','english','rw1',1,1,1,'B','["B"]'::jsonb,'multiple-choice','["The initial map of the underground tunnels was _______: engineers found several unexplored passages that required a revised survey.","A) exhaustive","B) provisional","C) redundant","D) indisputable"]'::jsonb,'["Provisional means subject to revision; newly discovered tunnels require updating the map."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-2','practice-test-8','english','rw1',2,1,1,'C','["C"]'::jsonb,'multiple-choice','["Although the town committee proposed several costly projects, its final recommendation was _______ and focused on repairing the existing footbridge.","A) extravagant","B) ambiguous","C) pragmatic","D) ornamental"]'::jsonb,'["Pragmatic means practical; repairing the existing bridge is the practical alternative to costly projects."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-3','practice-test-8','english','rw1',3,1,1,'A','["A"]'::jsonb,'multiple-choice','["The researcher''s statement was carefully _______: she acknowledged that the small sample prevented a firm conclusion about the entire population.","A) qualified","B) repudiated","C) generalized","D) amplified"]'::jsonb,'["Qualified means limited or made conditional; the researcher explicitly restricted the strength of the claim."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-4','practice-test-8','english','rw1',4,1,1,'B','["B"]'::jsonb,'multiple-choice','["The architect''s proposal was initially viewed as _______ because it relied on a material that had not yet been tested in large structures.","A) conventional","B) speculative","C) routine","D) conclusive"]'::jsonb,'["Speculative describes a proposal not yet supported by sufficient evidence."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-5','practice-test-8','english','rw1',5,1,1,'C','["C"]'::jsonb,'multiple-choice','["Despite sounding confident, the historian''s argument was _______ by newly discovered correspondence that contradicted its central date.","A) corroborated","B) illustrated","C) undermined","D) anticipated"]'::jsonb,'["Undermined means weakened; contradictory evidence challenges the argument."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-6','practice-test-8','english','rw1',6,1,1,'B','["B"]'::jsonb,'multiple-choice','["Choose the sentence that uses punctuation correctly.","A) The new library opened in June, it serves three neighborhoods.","B) The new library opened in June; it serves three neighborhoods.","C) The new library opened in June; and serves three neighborhoods.","D) The new library opened in June: and it serves three neighborhoods."]'::jsonb,'["A semicolon correctly joins two independent clauses without a coordinating conjunction."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-7','practice-test-8','english','rw1',7,1,1,'B','["B"]'::jsonb,'multiple-choice','["Choose the version that correctly combines these ideas: The prototype passed every safety test. The engineers nevertheless requested another inspection.","A) The prototype passed every safety test, nevertheless the engineers requested another inspection.","B) The prototype passed every safety test; nevertheless, the engineers requested another inspection.","C) The prototype passed every safety test nevertheless; the engineers requested another inspection.","D) The prototype passed every safety test, nevertheless, the engineers requested another inspection."]'::jsonb,'["Nevertheless is a conjunctive adverb; a semicolon separates the independent clauses and a comma follows the transition."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-8','practice-test-8','english','rw1',8,1,1,'A','["A"]'::jsonb,'multiple-choice','["Which sentence correctly introduces an explanation with a colon?","A) The trail was closed for one reason: a fallen tree blocked the entrance.","B) The trail was closed for: one reason a fallen tree blocked the entrance.","C) The trail was closed because: a fallen tree blocked the entrance.","D) The trail was closed for one reason, a fallen tree blocked the entrance."]'::jsonb,'["A colon can follow the complete clause ''The trail was closed for one reason'' to introduce its explanation."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-9','practice-test-8','english','rw1',9,1,1,'C','["C"]'::jsonb,'multiple-choice','["A school tracked participation in three clubs. Robotics: 26 students in September and 34 in October. Debate: 38 in September and 35 in October. Art: 20 in September and 31 in October. Which club had the largest numerical increase?","A) Robotics","B) Debate","C) Art","D) Robotics and Art tied"]'::jsonb,'["Art increased by 11, Robotics by 8, and Debate decreased by 3."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-10','practice-test-8','english','rw1',10,1,1,'C','["C"]'::jsonb,'multiple-choice','["A transit report shows on-time trips: Route A, 72 of 90; Route B, 84 of 120; Route C, 63 of 70. Which route had the highest on-time percentage?","A) Route A","B) Route B","C) Route C","D) Routes A and B tied"]'::jsonb,'["Route C was on time for 63/70 = 90%, compared with 80% for A and 70% for B."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-11','practice-test-8','english','rw1',11,1,1,'B','["B"]'::jsonb,'multiple-choice','["A lab measured plant growth with and without added nutrients. Species X: 12 cm without, 18 cm with. Species Y: 16 cm without, 17 cm with. Which statement is directly supported?","A) Both species grew exactly 6 cm more with nutrients.","B) Species X showed a larger increase than Species Y.","C) Species Y grew less with nutrients than without.","D) Added nutrients made both species reach the same height."]'::jsonb,'["Species X gained 6 cm whereas Species Y gained 1 cm."]'::jsonb,false,'verified','text'),
('practice-test-8:rw1-12','practice-test-8','english','rw1',12,1,1,'A','["A"]'::jsonb,'multiple-choice','["A researcher claims that a redesigned intersection reduced drivers'' average speed without reducing pedestrian use. Before the redesign: average speed 32 mph and 430 pedestrians per day. After: 25 mph and 460 pedestrians per day. Which conclusion follows?","A) Speeds fell, and pedestrian use rose.","B) Speeds fell because pedestrian use rose.","C) Pedestrian use fell while speeds remained constant.","D) The redesign alone proves a reduction in crashes."]'::jsonb,'["The two measurements support a speed decrease and pedestrian increase; they do not establish causation or crash outcomes."]'::jsonb,false,'verified','text')
